 expected={(p,v)for p in auth['programs']for v in TOKENS if not(p in FIRST4 and v=='PHYS768_TAG64x8')};actual={(p['program'],p['structure_variant'])for p in fields['points']};assert len(actual)==28 and actual==expected;config_records={};materialized_configs={}
